64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Dedicated audit logger. A successful owner create emits a single line here carrying the new
73	     * owner's id, customer code, registration date and membership level, so the create side-effect
74	     * can be audited independently of the application log.
75	     */
76	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
77	
78	    private final ClinicService clinicService;
79	
80	    private final OwnerMapper ownerMapper;
81	
82	    private final PetMapper petMapper;
83	
84	    private final VisitMapper visitMapper;
85	
86	    /**
87	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
88	     * and a domain containing at least one dot, with no whitespace in any segment.
89	     */
90	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
91	
92	    /**
93	     * Required national-number length per E.164 country code. A normalized telephone whose country
94	     * code appears here must carry exactly this many national digits after the code; Australia
95	     * ({@code +61}) requires 9 and the North American Numbering Plan ({@code +1}) requires 10.
96	     * Country codes not listed are only subject to the generic 8-to-15 total-digit rule.
97	     */
98	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTH = Map.of("61", 9, "1", 10);
99	
100	    /**
101	     * Maximum number of owners permitted in a single city. A create whose city already holds this many
102	     * owners (compared case-insensitively) is rejected with a 409 Conflict.
103	     */
104	    private static final int MAX_OWNERS_PER_CITY = 50;
105	
106	    /**
107	     * Maximum number of owners that may be registered on a single day (by registration date). A create
108	     * attempted once this many owners already carry today's registration date is rejected with a
109	     * 429 Too Many Requests.
110	     */
111	    private static final int MAX_OWNERS_PER_DAY = 100;
112	
113	    /**
114	     * Threshold above which a create is flagged with a bulk-signup warning. When more than this many
115	     * owners already carry the new owner's registration date, the created owner is flagged
116	     * ({@code bulkSignupWarning} true); otherwise the flag is false.
117	     */
118	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
119	
120	    /**
121	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
122	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
123	     */
124	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
125	        "ST", "STREET",
126	        "RD", "ROAD",
127	        "AVE", "AVENUE");
128	
129	    public OwnerRestControllerV1(ClinicService clinicService,
130	                                 OwnerMapper ownerMapper,
131	                                 PetMapper petMapper,
132	                                 VisitMapper visitMapper) {
133	        this.clinicService = clinicService;
134	        this.ownerMapper = ownerMapper;
135	        this.petMapper = petMapper;
136	        this.visitMapper = visitMapper;
137	    }
138	
139	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
140	    @Override
141	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
142	        Collection<Owner> owners;
143	        if (lastName != null) {
144	            owners = this.clinicService.findOwnerByLastName(lastName);
145	        } else {
146	            owners = this.clinicService.findAllOwners();
147	        }
148	        if (owners.isEmpty()) {
149	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
150	        }
151	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
152	    }
153	
154	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
155	    @Override
156	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
157	        Owner owner = this.clinicService.findOwnerById(ownerId);
158	        if (owner == null) {
159	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
160	        }
161	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
162	    }
163	
164	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
165	    @Override
166	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
167	        validateRequiredFields(ownerFieldsDto);
168	        HttpHeaders headers = new HttpHeaders();
169	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
170	        LocalDate registrationDate = Owner.resolveRegistrationDate(owner.getRegistrationDate());
171	        owner.setRegistrationDate(registrationDate);
172	        requireDailyCapacity(registrationDate);
173	        requireCityHasCapacity(owner.getCity());
174	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
175	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
176	            joinHousehold(owner);
177	        }
178	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
179	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
180	        requireUniqueIdentity(owner);
181	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
182	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
183	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
184	        this.clinicService.saveOwner(owner);
185	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
186	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
187	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
188	        headers.setLocation(UriComponentsBuilder.newInstance()
189	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
190	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
191	    }
192	
193	    /**
194	     * Rejects a create once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the new owner's
195	     * adjusted business-day registration date. Existing owners are counted by {@code registrationDate}
196	     * equal to that date, before the new owner is saved, so the count reflects only the owners that
197	     * existed prior to this create.
198	     *
199	     * @param registrationDate the new owner's effective registration date, already rolled forward onto
200	     *     a business day
201	     * @throws DailyOwnerLimitException if {@value #MAX_OWNERS_PER_DAY} or more owners are already
202	     *     registered on that business day
203	     */
204	    private void requireDailyCapacity(LocalDate registrationDate) {
205	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
206	            throw new DailyOwnerLimitException(registrationDate);
207	        }
208	    }
209	
210	    /**
211	     * Counts the existing owners whose registration date equals the given business-day date. This is
212	     * evaluated before the new owner is saved, so it reflects only the owners that existed prior to
213	     * this create. It is the single definition of the per-day count shared by the daily-limit rule and
214	     * the bulk-signup warning.
215	     *
216	     * @param registrationDate the effective business-day registration date to count against
217	     * @return the number of pre-existing owners registered on that date
218	     */
219	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
220	        return this.clinicService.findAllOwners().stream()
221	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
222	            .count();
223	    }
224	
225	    /**
226	     * Rejects an owner whose city already contains the maximum allowed number of owners
227	     * ({@value #MAX_OWNERS_PER_CITY}). Existing owners are counted by city compared case-insensitively,
228	     * before the new owner is saved, so the count reflects only the owners that existed prior to this
229	     * create.
230	     *
231	     * @param city the city of the owner being created
232	     * @throws CityOwnerLimitException if the city already holds {@value #MAX_OWNERS_PER_CITY} or more owners
233	     */
234	    private void requireCityHasCapacity(String city) {
235	        long cityOwnerCount = this.clinicService.findAllOwners().stream()
236	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
237	            .count();
238	        if (cityOwnerCount >= MAX_OWNERS_PER_CITY) {
239	            throw new CityOwnerLimitException(city);
240	        }
241	    }
242	
243	    /**
244	     * Generates the customer code for a newly created owner, formatted
245	     * {@code '<CITY3>-<LAST3>-<NNNN>'}. {@code CITY3} is the upper-cased first three letters of the
246	     * city, {@code LAST3} the upper-cased first three letters of the last name, and {@code NNNN} a
247	     * per-city, 4-digit zero-padded sequence equal to one more than the number of owners already in
248	     * that city (e.g. {@code 'LON-SMI-0007'}).
249	     *
250	     * @param city the owner's city
251	     * @param lastName the owner's last name
252	     * @return the generated customer code
253	     */
254	    private String generateCustomerCode(String city, String lastName) {
255	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
256	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
257	        int sequence = (int) this.clinicService.findAllOwners().stream()
258	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
259	            .count() + 1;
260	        return String.format("%s-%s-%04d", city3, last3, sequence);
261	    }
262	
263	    /**
264	     * Counts the existing owners that already share the given first name and last name, compared
265	     * case-insensitively. This is evaluated before the new owner is saved, so it reflects only the
266	     * owners that existed prior to this create.
267	     *
268	     * @param firstName the first name of the owner being created
269	     * @param lastName the last name of the owner being created
270	     * @return the number of pre-existing namesakes
271	     */
272	    private int countNamesakes(String firstName, String lastName) {
273	        return (int) this.clinicService.findAllOwners().stream()
274	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
275	                && equalsIgnoreCase(existing.getLastName(), lastName))
276	            .count();
277	    }
278	
279	    /**
280	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
281	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
282	     *
283	     * @param a the first value, possibly {@code null}
284	     * @param b the second value, possibly {@code null}
285	     * @return whether the values are equal ignoring case
286	     */
287	    private boolean equalsIgnoreCase(String a, String b) {
288	        return a == null ? b == null : a.equalsIgnoreCase(b);
289	    }
290	
291	    /**
292	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
293	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
294	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
295	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
296	     *
297	     * @param ownerFieldsDto the submitted owner fields
298	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
299	     */
300	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
301	        List<String> invalidFields = new ArrayList<>();
302	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
303	            invalidFields.add("firstName");
304	        }
305	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
306	            invalidFields.add("lastName");
307	        }
308	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
309	            invalidFields.add("address");
310	        }
311	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
312	            invalidFields.add("city");
313	        }
314	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
315	            invalidFields.add("telephone");
316	        }
317	        if (!invalidFields.isEmpty()) {
318	            throw new InvalidOwnerFieldsException(invalidFields);
319	        }
320	    }
321	
322	    /**
323	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
324	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
325	     * what gets stored and returned.
326	     *
327	     * @param telephone the raw telephone value from the request
328	     * @return the normalized E.164 telephone number
329	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
330	     */
331	    private String normalizeTelephone(String telephone) {
332	        String e164 = toE164(telephone);
333	        if (e164 == null) {
334	            throw new InvalidOwnerFieldsException(List.of("telephone"));
335	        }
336	        return e164;
337	    }
338	
339	    /**
340	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
341	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
342	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
343	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
344	     * it contains 8 to 15 digits after the {@code '+'} and, for a recognized country code (see
345	     * {@link #NATIONAL_NUMBER_LENGTH}), carries exactly that country's required national-number length.
346	     *
347	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
348	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
349	     *
350	     * @param telephone the raw telephone value, possibly {@code null}
351	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
352	     */
353	    private String toE164(String telephone) {
354	        if (telephone == null) {
355	            return null;
356	        }
357	        String cleaned = telephone.replaceAll("[ \\-()]", "");
358	        String digits;
359	        if (cleaned.startsWith("+")) {
360	            digits = cleaned.substring(1);
361	        } else {
362	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
363	            digits = "61" + national;
364	        }
365	        if (!digits.matches("[0-9]{8,15}")) {
366	            return null;
367	        }
368	        if (!nationalNumberLengthValid(digits)) {
369	            return null;
370	        }
371	        return "+" + digits;
372	    }
373	
374	    /**
375	     * Checks a normalized E.164 digit string (country code followed by national digits, without the
376	     * leading {@code '+'}) against the per-country national-number length rule. For a country code
377	     * listed in {@link #NATIONAL_NUMBER_LENGTH} the national part must have exactly the required length
378	     * (e.g. {@code '+61'} needs 9 national digits, {@code '+1'} needs 10); any other country code is
379	     * accepted, leaving only the generic total-length rule to apply.
380	     *
381	     * @param digits the E.164 digits without the leading {@code '+'}
382	     * @return {@code true} if the national-number length matches the country code's requirement
383	     */
384	    private boolean nationalNumberLengthValid(String digits) {
385	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTH.entrySet()) {
386	            String code = entry.getKey();
387	            if (digits.startsWith(code)) {
388	                return digits.length() - code.length() == entry.getValue();
389	            }
390	        }
391	        return true;
392	    }
393	
394	    /**
395	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
396	     * {@code null}. When present, the value must be a syntactically valid address; it is then stored
397	     * and returned lower-cased.
398	     *
399	     * @param email the raw email value from the request, possibly {@code null}
400	     * @return the lower-cased email, or {@code null} when none was supplied
401	     * @throws InvalidOwnerFieldsException if a value is present but not a valid email address
402	     */
403	    private String normalizeEmail(String email) {
404	        if (!StringUtils.hasText(email)) {
405	            return null;
406	        }
407	        String trimmed = email.trim();
408	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
409	            throw new InvalidOwnerFieldsException(List.of("email"));
410	        }
411	        return trimmed.toLowerCase(Locale.ROOT);
412	    }
413	
414	    /**
415	     * Rejects an owner whose whole identity key is already used by an existing owner. This is the
416	     * single consolidated duplicate check: the identity key ({@link Owner#getIdentityKey()}) is the
417	     * owner's normalized telephone, email (empty when absent) and household id joined with
418	     * {@code '|'}, and a create is a duplicate only when the new owner's whole key equals an existing
419	     * owner's. Because the telephone is part of the key, two members of the same household
420	     * (same {@code householdId}) with different telephones have different identity keys and are both
421	     * allowed.
422	     *
423	     * @param owner the owner being created, with its normalized telephone, email and household id set
424	     * @throws DuplicateIdentityException if another owner already has this identity key
425	     */
426	    private void requireUniqueIdentity(Owner owner) {
427	        String identityKey = owner.getIdentityKey();
428	        boolean inUse = this.clinicService.findAllOwners().stream()
429	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
430	        if (inUse) {
431	            throw new DuplicateIdentityException(identityKey);
432	        }
433	    }
434	
435	    /**
436	     * Returns the existing owners that belong to the same household as the given last name and
437	     * address, i.e. those whose last name and address match case-insensitively and with runs of
438	     * whitespace collapsed to a single space.
439	     *
440	     * @param lastName the last name to match
441	     * @param address the address to match
442	     * @return the matching owners (possibly empty, never {@code null})
443	     */
444	    private List<Owner> findHouseholdMembers(String lastName, String address) {
445	        String normalizedLastName = normalizeForHousehold(lastName);
446	        String normalizedAddress = normalizeAddress(address);
447	        return this.clinicService.findAllOwners().stream()
448	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
449	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
450	            .toList();
451	    }
452	
453	    /**
454	     * Joins the owner being created to the shared household of any existing owner(s) that have the
455	     * same last name and address (compared case-insensitively with collapsed whitespace). Every
456	     * member of the household - the existing owners and the new one - is assigned the same stable
457	     * {@code householdId}, so the shared identifier can be read back from any of them.
458	     *
459	     * <p>When no existing owner shares the household there is nobody to share an identifier with, so
460	     * the owner is left without a {@code householdId}.
461	     *
462	     * <p>Every member of the household - the existing owners and the new one - is also stamped with
463	     * the household's member count after this create ({@code householdSize}), so the shared size can
464	     * be read back from any of them.
465	     *
466	     * @param owner the owner being created, whose {@code householdId} is set when a household is joined
467	     */
468	    private void joinHousehold(Owner owner) {
469	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
470	        if (members.isEmpty()) {
471	            return;
472	        }
473	        String householdId = computeHouseholdId(owner.getLastName(), owner.getAddress());
474	        int householdSize = members.size() + 1;
475	        owner.setHouseholdId(householdId);
476	        owner.setHouseholdSize(householdSize);
477	        for (Owner member : members) {
478	            member.setHouseholdId(householdId);
479	            member.setHouseholdSize(householdSize);
480	            this.clinicService.saveOwner(member);
481	        }
482	    }
483	
484	    /**
485	     * Computes the stable, shared household identifier for a last name and address. The value is
486	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last
487	     * name and address, so every owner in the same household computes the same identifier.
488	     *
489	     * @param lastName the last name of the household
490	     * @param address the address of the household
491	     * @return the household identifier, formatted {@code 'HH-<12 upper-case hex digits>'}
492	     */
493	    private String computeHouseholdId(String lastName, String address) {
494	        String key = normalizeForHousehold(lastName) + "\n" + normalizeAddress(address);
495	        try {
496	            byte[] digest = MessageDigest.getInstance("SHA-256")
497	                .digest(key.getBytes(StandardCharsets.UTF_8));
498	            StringBuilder hex = new StringBuilder();
499	            for (int i = 0; i < 6; i++) {
500	                hex.append(String.format("%02X", digest[i]));
501	            }
502	            return "HH-" + hex;
503	        } catch (NoSuchAlgorithmException e) {
504	            throw new IllegalStateException("SHA-256 algorithm not available", e);
505	        }
506	    }
507	
508	    /**
509	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
510	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
511	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
512	     *
513	     * @param value the raw value, possibly {@code null}
514	     * @return the normalized value
515	     */
516	    private String normalizeForHousehold(String value) {
517	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
518	    }
519	
520	    /**
521	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
522	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
523	     * value yields an empty string.
524	     *
525	     * @param value the raw value, possibly {@code null}
526	     * @return the trimmed, whitespace-collapsed value
527	     */
528	    private String collapseWhitespace(String value) {
529	        if (value == null) {
530	            return "";
531	        }
532	        return value.trim().replaceAll("\\s+", " ");
533	    }
534	
535	    /**
536	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
537	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
538	     * is upper-cased, and common street-type abbreviations are expanded as whole words
539	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
540	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
541	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
542	     *
543	     * @param address the raw address value, possibly {@code null}
544	     * @return the normalized address
545	     */
546	    private String normalizeAddress(String address) {
547	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
548	        if (collapsed.isEmpty()) {
549	            return "";
550	        }
551	        String[] tokens = collapsed.split(" ");
552	        StringBuilder normalized = new StringBuilder();
553	        for (int i = 0; i < tokens.length; i++) {
554	            if (i > 0) {
555	                normalized.append(' ');
556	            }
557	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
558	        }
559	        return normalized.toString();
560	    }
561	
562	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
563	    @Override
564	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
565	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
566	        if (currentOwner == null) {
567	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
568	        }
569	        currentOwner.setAddress(ownerFieldsDto.getAddress());
570	        currentOwner.setCity(ownerFieldsDto.getCity());
571	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
572	        currentOwner.setLastName(ownerFieldsDto.getLastName());
573	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
574	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
575	        this.clinicService.saveOwner(currentOwner);
576	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
577	    }
578	
579	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
580	    @Transactional
581	    @Override
582	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
583	        Owner owner = this.clinicService.findOwnerById(ownerId);
584	        if (owner == null) {
585	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
586	        }
587	        this.clinicService.deleteOwner(owner);
588	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
589	    }
590	
591	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
592	    @Override
593	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
594	        Owner owner = this.clinicService.findOwnerById(ownerId);
595	        if (owner == null) {
596	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
597	        }
598	        HttpHeaders headers = new HttpHeaders();
599	        Pet pet = petMapper.toPet(petFieldsDto);
600	        owner.setId(ownerId);
601	        pet.setOwner(owner);
602	        pet.getType().setName(null);
603	        this.clinicService.savePet(pet);
604	        PetDto petDto = petMapper.toPetDto(pet);
605	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
606	            .buildAndExpand(pet.getId()).toUri());
607	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
608	    }
609	
610	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
611	    @Override
612	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
613	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
614	        if (currentOwner != null) {
615	            Pet currentPet = this.clinicService.findPetById(petId);
616	            if (currentPet != null) {
617	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
618	                currentPet.setName(petFieldsDto.getName());
619	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
620	                this.clinicService.savePet(currentPet);
621	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
622	            }
623	        }
624	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
625	    }
626	
627	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
628	    @Override
629	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
630	        HttpHeaders headers = new HttpHeaders();
631	        Visit visit = visitMapper.toVisit(visitFieldsDto);
632	        Pet pet = new Pet();
633	        pet.setId(petId);
634	        visit.setPet(pet);
635	        this.clinicService.saveVisit(visit);
636	        VisitDto visitDto = visitMapper.toVisitDto(visit);
637	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
638	            .buildAndExpand(visit.getId()).toUri());
639	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
640	    }
641	
642	
643	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
644	    @Override
645	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
646	        Owner owner = this.clinicService.findOwnerById(ownerId);
647	        if (owner != null) {
648	            Pet pet = owner.getPet(petId);
649	            if (pet != null) {
650	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
651	            }
652	        }
653	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
654	    }
655	}
