188	    /**
189	     * The owner's identity key, the single derived value used for duplicate detection. It is the
190	     * owner's normalized telephone, email (empty when absent) and household id joined with
191	     * {@code '|'} ({@code '<telephone>|<email>|<householdId>'}); any absent ({@code null}) component
192	     * contributes an empty string. Two owners are duplicates exactly when their whole identity keys
193	     * are equal, so two members of the same household with different telephones differ here and are
194	     * both allowed.
195	     *
196	     * @return the derived identity key
197	     */
198	    public String getIdentityKey() {
199	        return (this.telephone == null ? "" : this.telephone) + "|"
200	            + (this.email == null ? "" : this.email) + "|"
201	            + (this.householdId == null ? "" : this.householdId);
202	    }
