236	    /**
237	     * Stamps the effective registration date exactly once on insert, so every newly persisted owner
238	     * carries a resolved, business-day registration date (see {@link #resolveRegistrationDate}).
239	     */
240	    @PrePersist
241	    void onCreate() {
242	        this.registrationDate = resolveRegistrationDate(this.registrationDate);
243	    }
244	
245	    /**
246	     * Resolves the effective registration date and rolls it onto a business day. An absent
247	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
248	     * The resulting date is then rolled forward so it never falls on a weekend: a Saturday or Sunday
249	     * becomes the following Monday, while any weekday is returned unchanged.
250	     *
251	     * <p>This is the single definition of both the defaulting and the business-day roll, used
252	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
253	     * stamps the owner and by the create endpoint that counts owners per business day.
254	     *
255	     * @param supplied the registration date from the request, or {@code null} when none was supplied
256	     * @return the effective registration date, guaranteed to fall on a business day
257	     */
258	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
259	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
260	        return switch (effective.getDayOfWeek()) {
261	            case SATURDAY -> effective.plusDays(2);
262	            case SUNDAY -> effective.plusDays(1);
263	            default -> effective;
264	        };
265	    }
266	
267	    protected Set<Pet> getPetsInternal() {
268	        if (this.pets == null) {
269	            this.pets = new HashSet<>();
