303	    /**
304	     * Return the Pet with the given name, or null if none found for this Owner.
305	     *
306	     * @param name to test
307	     * @return true if pet name is already in use
308	     */
309	    public Pet getPet(String name, boolean ignoreNew) {
310	        name = name.toLowerCase();
311	        for (Pet pet : getPetsInternal()) {
312	            if (!ignoreNew || !pet.isNew()) {
313	                String compName = pet.getName();
314	                compName = compName.toLowerCase();
315	                if (compName.equals(name)) {
316	                    return pet;
317	                }
318	            }
319	        }
320	        return null;
321	    }
322	
323	    public Pet getPet(Integer petId) {
324	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
325	    }
326	
327	    @Override
328	    public String toString() {
329	        return new ToStringCreator(this)
330	
331	            .append("id", this.getId())
332	            .append("new", this.isNew())
333	            .append("lastName", this.getLastName())
334	            .append("firstName", this.getFirstName())
335	            .append("address", this.address)
336	            .append("city", this.city)
337	            .append("telephone", this.telephone)
338	            .toString();
339	    }
340	}
